    'txb.novideo': 'This WebView2 cannot make mp4 videos: update Microsoft Edge WebView2, or send a still picture.', 'txb.big': 'The result is over 16 MB: use a shorter video.', 'txb.fail': 'The file could not be made ({0}).', 'txb.loading': 'Opening the file…', 'txb.cut': 'Moving: {0} s, cut short: the rest does not fit in memory', 'txb.saving': 'Saving on this PC…', 'txb.saved': 'Saved on this PC. Sending it to the screen takes a while: the device card shows how it goes.', 'txb.nosave': 'Not saved: {0}. The previous file and the screen settings are unchanged, try again.', 'txb.e.open': 'the file could not be made in the settings folder', 'txb.e.write': 'writing it failed (is the disk full?)', 'txb.e.replace': 'the previous file is in use (it may be going to the screen right now)', 'txb.e.bad': 'the app did not take the file', 'txb.e.wait': 'the app did not answer', 'txb.stopped': 'Video making stopped: nothing was saved, your work is still here.',
